sysevent_script_action.script:
// Queue up the import of the oldest attachment on 
// the Vendor DataQueue data source.
queueNewImport();

function queueNewImport() {
    // Queue the file up for import via a new data source
    // and scheduled import
    const app_id = "52739d78c35b7290c134bf12b4013100"; // "Import Visibility"

    // A new file just arrived on this data source
    const vendor_data_queue_ds_name = "Vendor Data Queue";
    const vendor_data_queue_ds_sys_id = getDataSourceSysId(app_id, vendor_data_queue_ds_name);

    if (!vendor_data_queue_ds_sys_id) throw vendor_data_queue_ds_name + " data source not found!";

    // We will move it to this data source, deleting any existing, then run an import
    const vendor_data_ds_name = "Vendor Data";
    const vendor_data_ds_sys_id = getDataSourceSysId(app_id, vendor_data_ds_name);

    if (!vendor_data_ds_sys_id) throw vendor_data_ds_name + " data source not found!";

    // And then set the run start on this scheduled import
    const scheduled_import_sys_id = getScheduledImportSysId(app_id, "scheduled_import_set", "Vendor Data");

    if (!scheduled_import_sys_id) throw "Vendor Data Scheduled Import Set not found!";

    // Get the oldest attachment on this data source - it may not be the 
    // file that just arrived. If no attachment exists, exit.
    var gr_attachment = new GlideRecord("sys_attachment");
    gr_attachment.addQuery("table_sys_id", vendor_data_queue_ds_sys_id);
    gr_attachment.addQuery("table_name", "sys_data_source");
    gr_attachment.orderBy("sys_created_on");
    gr_attachment.setLimit(1);
    gr_attachment.query();
    if (!gr_attachment.next()) {
        gs.info("No attachment found for Vendor Data Queue");
        return;
    }
    var attachment_sys_id = gr_attachment.getValue("sys_id");

    var inputs = {};
	inputs['import_set_table'] = 'x_42999_import_v_0_vendor_hardware_rows';
    inputs['application_id'] = app_id;
    inputs['from_data_source_sys_id'] = vendor_data_queue_ds_sys_id;
    inputs['to_data_source_sys_id'] = vendor_data_ds_sys_id;
    inputs['attachment_sys_id'] = attachment_sys_id;
	inputs['scheduled_import_table_name'] = "scheduled_import_set";
    inputs['scheduled_import_sys_id'] = scheduled_import_sys_id;


    sn_fd.FlowAPI
        .getRunner()
        .subflow('x_42999_import_v_0.import_vendor_data')
        .inBackground()
        .withInputs(inputs)
        .run();
}

function getDataSourceSysId(app_id, name) {
    var result = null;
    var gr = new GlideRecord("sys_data_source");
    gr.addQuery("sys_scope", app_id);
    gr.addQuery("name", name);
    gr.setLimit(1);
    gr.query();
    if (gr.next()) result = gr.getValue("sys_id");
    return result;
}

function getScheduledImportSysId(app_id, tableName, jobName) {
    var result = null;
    var gr = new GlideRecord(tableName);
    gr.addQuery("sys_scope", app_id);
    gr.addQuery("name", jobName);
    gr.setLimit(1);
    gr.query();
    if (gr.next()) result = gr.getValue("sys_id");
    return result;
}
